B.bqr=new A.dL("Questo evento \xe8 stato annullato da chi lo organizzava. Se avevi comprato un biglietto, il rimborso \xe8 gi\xe0 partito.",B.ew,B.bo,null)
B.brN=new A.N(B.eQ,B.bqr,null)
B.bq6=new A.dL("L'ultimo addebito non \xe8 riuscito. Aggiorna la carta, altrimenti il piano torner\xe0 a Go Flex.",B.ew,B.bo,null)
B.brO=new A.N(B.Ls,B.bq6,null)
